        \def\r{3}
        \path 
        (0,0) coordinate (O)
        (O)++(150:2.5*\r) coordinate (K)
        (O)++(30:\r) coordinate (O1)
        (K)++(20:3*\r) coordinate (Mx)
        ;
        \begin{scope}
            \path ($(K)!0.5!(O)$) coordinate (K1);
            \path[name path=dtronK1] let\p2=($(K1)-(K)$) in (K1) circle({veclen(\x2,\y2)});
            \path[name path=dtronT] let \p1=($(O)-(O1)$) in (O) circle ({veclen(\x1,\y1)});
            \path[name intersections={of=dtronK1 and dtronT, by={B,A}}];
            \draw (A)--(K)--(B);
            \draw (O) circle(\r) (K)--(O) (O)--(A) (O)--(B)--(A);
        \end{scope}
        \path 
        ($(K)!(O)!(Mx)$) coordinate (H)
        (intersection of O--H and A--B) coordinate (I)
        (intersection of O--K and A--B) coordinate (M)
        ;
        \draw (O)--(H)(K)--(Mx)node[above]{$d$} (A)--(H)(K)--(I);
        \foreach \x/\y/\z in {K/B/O,K/A/O,O/H/K}{\draw pic[draw,angle radius=3mm]{right angle=\x--\y--\z};}

    \filldraw[black] (I) circle (1pt) node[above right] {$H$};
    \filldraw[black] (M) circle (1pt) node[below right] {$J$};
    \filldraw[black] (K) circle (1pt) node[above] {$L$};
   \filldraw[black] (B) circle (1pt) node[above right]{$R$};
    \filldraw[black] (A) circle (1pt) node[below left] {$U$};
     \filldraw[black] (H) circle (1pt) node[above] {$V$};
    \filldraw[black] (O) circle (1pt) node[below ] {$O$};
  \end{tikzpicture}
\end{center}
a) $\widehat{LUO} = 90^{\circ}$ vì ${LU}$ là tiếp tuyến của $({O})$ (gt)\\
$\widehat{LVO} = 90^{\circ}$ (gt)\\
Suy ra tam giác ${LUO}$ vuông tại ${U}$, tam giác ${LVO}$ vuông tại ${V}$.\\
Do đó ${U, V}$ thuộc đường tròn đường kính ${OL}$.\\
Vậy tứ giác ${LUOV}$ nội tiếp được trong đường tròn.\\
Các đỉnh ${V, R, U}$ cùng nhìn cạnh ${OL}$ dưới một góc vuông\\
nên năm điểm ${L,R,U,O,V}$ cùng thuộc đường tròn đường kính ${OL}$ suy ra\\
$\widehat {UVH} =\widehat {URO}$ (hai góc nội tiếp cùng chắn cung ${UO}$).\\
Xét tam giác ${HUV}$ và tam giác ${HRO}$ có:\\
$\widehat {VHU}=\widehat {RHO}$ (đối đỉnh)\\
và $\widehat{UVH}=\widehat  {URO}$ (cmt)\\
Do đó $\Delta {HUV} \backsim \Delta {HOR} (g.g)$\\
$\dfrac{HU}{HV}= \dfrac{HO}{HR}$ suy ra ${HU\cdot HO}={HV\cdot HR}$\\
Gọi ${J}$ là giao điểm của ${OL}$ và ${UR}$\\
Theo tính chất tiếp tuyến ta có ${LU = LR}$;\\
Lại có ${OU = OR = R}$ nên ${OL}$ là đường trung trực của ${UR}$, suy ra ${UR \perp OL}$ tại ${J}$ và ${JU = JR}$.\\
Ta có: $\triangle {OJH} \sim \triangle {OVL}$ (g.g) suy ra\\
$OH= \dfrac{OL \cdot OJ}{OV} = \dfrac{OU^{2}}{OV} = \dfrac{R^{2}}{OV} = \dfrac{R^{2}}{R\sqrt{3}} = \dfrac{R}{\sqrt{3}}$.\\
Xét $\triangle {OUL}$ vuông tại ${U}$, có\\
$OU^{2} = OJ \cdot OL \implies OJ = \dfrac{OU^{2}}{OL} = \dfrac{R^{2}}{2R} = \dfrac{R}{2}$.\\
Suy ra\\
$LJ = OL - OJ = 2R - \dfrac{R}{2} = \dfrac{3R}{2}$.\\
$UJ^{2} = OJ \cdot LJ = \dfrac{R}{2} \cdot \dfrac{3R}{2} = \dfrac{3R^{2}}{4} \implies UJ = \dfrac{R\sqrt{3}}{2}$.\\
Xét $\triangle {OJH}$ vuông tại ${J}$, có\\
$JH = \sqrt{OH^{2} - OJ^{2}} = \sqrt{\left(\dfrac{R}{\sqrt{3}}\right)^{2} - \left(\dfrac{R}{2}\right)^{2} } = \dfrac{R\sqrt{3} }{6}$.\\
Suy ra\\
$UH = UJ + JH = \dfrac{R\sqrt{3}}{2} + \dfrac{R\sqrt{3}}{6} = \dfrac{2R\sqrt{3}}{3}$.\\
Diện tích $\triangle {ULH}$ là\\
$S = \dfrac{1}{2} \cdot UH \cdot LJ = \dfrac{1}{2} \cdot \dfrac{3R}{2} \cdot \dfrac{2R\sqrt{3}}{3} = \dfrac{R^{2}\sqrt{3}}{2}$.
}\end{ex}

